import React, { useEffect, useRef } from 'react';

export type TabKey = 'accueil' | 'apropos' | 'realisations' | 'contact';

const tabs: { key: TabKey; label: string }[] = [
  { key: 'accueil', label: 'Accueil' },
  { key: 'apropos', label: 'À propos de nous' },
  { key: 'realisations', label: 'Nos réalisations' },
  { key: 'contact', label: 'Contactez-nous' },
];

export default function TabNav({
  active,
  onChange,
}: {
  active: TabKey;
  onChange: (key: TabKey) => void;
}) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const sliderRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const wrap = wrapRef.current!;
    const slider = sliderRef.current!;
    const idx = tabs.findIndex((t) => t.key === active);
    const el = wrap.querySelectorAll<HTMLButtonElement>('button')[idx];
    if (el && slider) {
      const { offsetLeft, offsetWidth } = el;
      slider.style.transform = `translateX(${offsetLeft}px)`;
      slider.style.width = `${offsetWidth}px`;
    }
  }, [active]);

  return (
    <div className="tabs" role="tablist" aria-label="Sections du site" ref={wrapRef}>
      <span className="slider" aria-hidden="true" ref={sliderRef} />
      {tabs.map(({ key, label }) => (
        <button
          key={key}
          className="tab"
          role="tab"
          aria-selected={active === key}
          onClick={() => onChange(key)}
        >
          {label}
        </button>
      ))}
    </div>
  );
}
